"use client"

import * as React from "react"
import { Slot } from "@radix-ui/react-slot"

import { cn } from "@/lib/utils"
import { Scrollbar } from "@/components/ui/scrollbar"

type DialogContextValue = {
  open: boolean
  setOpen: (open: boolean) => void
  alert: boolean
  titleId: string
  descriptionId: string
}

const DialogContext = React.createContext<DialogContextValue | null>(null)

function useDialog() {
  const ctx = React.useContext(DialogContext)
  if (!ctx) throw new Error("Dialog parts must sit inside <Dialog>.")
  return ctx
}

type DialogProps = {
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  /** A question that needs an answer: role alertdialog, and pointing outside doesn't close it. */
  alert?: boolean
  children: React.ReactNode
}

/** The question, set large. Built on the native <dialog>, so focus, Escape and the top layer are the browser's. */
function Dialog({ open: controlled, defaultOpen = false, onOpenChange, alert = false, children }: DialogProps) {
  const [uncontrolled, setUncontrolled] = React.useState(defaultOpen)
  const open = controlled ?? uncontrolled
  const setOpen = React.useCallback(
    (next: boolean) => {
      if (controlled === undefined) setUncontrolled(next)
      onOpenChange?.(next)
    },
    [controlled, onOpenChange],
  )
  const id = React.useId()
  const value = React.useMemo(
    () => ({ open, setOpen, alert, titleId: `${id}-title`, descriptionId: `${id}-description` }),
    [open, setOpen, alert, id],
  )
  return <DialogContext.Provider value={value}>{children}</DialogContext.Provider>
}

function DialogTrigger({ asChild = false, onClick, ...props }: React.ComponentProps<"button"> & { asChild?: boolean }) {
  const { open, setOpen } = useDialog()
  const Comp = asChild ? Slot : "button"
  return (
    <Comp
      data-slot="dialog-trigger"
      aria-haspopup="dialog"
      aria-expanded={open}
      onClick={(e: React.MouseEvent<HTMLButtonElement>) => {
        onClick?.(e)
        if (!e.defaultPrevented) setOpen(true)
      }}
      {...(asChild ? {} : { type: "button" as const })}
      {...props}
    />
  )
}

/**
 * The bare <dialog>, opened as a modal while the Dialog is open. The sheet and
 * the drawer are surfaces too; they bring their own class.
 * Focus goes to the element marked data-autofocus, or the browser's first choice.
 * Taller than the window, it scrolls, on the scrollbar's rail.
 */
function DialogSurface({ className, children, onClick, ...props }: React.ComponentProps<"dialog">) {
  const { open, setOpen, alert, titleId, descriptionId } = useDialog()
  const ref = React.useRef<HTMLDialogElement>(null)

  React.useEffect(() => {
    const d = ref.current
    if (!d) return
    d.setAttribute("closedby", alert ? "closerequest" : "any")
    if (open && !d.open) {
      d.showModal()
      d.querySelector<HTMLElement>("[data-autofocus]")?.focus()
    } else if (!open && d.open) d.close()
  }, [open, alert])

  React.useEffect(() => {
    const d = ref.current
    if (!d) return
    const closed = () => setOpen(false)
    d.addEventListener("close", closed)
    return () => d.removeEventListener("close", closed)
  }, [setOpen])

  return (
    <dialog
      ref={ref}
      role={alert ? "alertdialog" : undefined}
      aria-labelledby={titleId}
      aria-describedby={descriptionId}
      className={className}
      onClick={(e) => {
        onClick?.(e)
        // Pointing outside puts it away (where the browser lacks closedby="any").
        const d = ref.current
        if (alert || !d || e.target !== d) return
        const r = d.getBoundingClientRect()
        if (e.clientX < r.left || e.clientX > r.right || e.clientY < r.top || e.clientY > r.bottom) d.close()
      }}
      {...props}
    >
      {children}
      <Scrollbar />
    </dialog>
  )
}

function DialogContent({ className, ...props }: React.ComponentProps<"dialog">) {
  return <DialogSurface data-slot="dialog-content" className={cn("db-dialog", className)} {...props} />
}

/** A frame row over the question: what this is, a hairline, and one fact. */
function DialogMeta({ className, ...props }: React.ComponentProps<"div">) {
  return <div data-slot="dialog-meta" className={cn("db-meta db-dialog-meta", className)} {...props} />
}

function DialogTitle({ className, ...props }: React.ComponentProps<"h2">) {
  const { titleId } = useDialog()
  return <h2 data-slot="dialog-title" id={titleId} className={cn("db-dialog-title", className)} {...props} />
}

function DialogDescription({ className, ...props }: React.ComponentProps<"p">) {
  const { descriptionId } = useDialog()
  return <p data-slot="dialog-description" id={descriptionId} className={cn("db-dialog-body", className)} {...props} />
}

function DialogActions({ className, ...props }: React.ComponentProps<"div">) {
  return <div data-slot="dialog-actions" className={cn("db-dialog-actions", className)} {...props} />
}

function DialogClose({ asChild = false, onClick, ...props }: React.ComponentProps<"button"> & { asChild?: boolean }) {
  const { setOpen } = useDialog()
  const Comp = asChild ? Slot : "button"
  return (
    <Comp
      data-slot="dialog-close"
      onClick={(e: React.MouseEvent<HTMLButtonElement>) => {
        onClick?.(e)
        if (!e.defaultPrevented) setOpen(false)
      }}
      {...(asChild ? {} : { type: "button" as const })}
      {...props}
    />
  )
}

export {
  Dialog,
  DialogTrigger,
  DialogSurface,
  DialogContent,
  DialogMeta,
  DialogTitle,
  DialogDescription,
  DialogActions,
  DialogActions as DialogFooter,
  DialogClose,
  useDialog,
}

@layer components {
  /* ── db-dialog ── the question, set large */
  .db-dialog {
    border: 0; margin: auto; padding: var(--db-space-8) var(--db-space-7) var(--db-space-7);
    width: min(44rem, calc(100vw - 2 * var(--db-margin))); max-width: none;
    background: var(--db-paper); color: var(--db-graphite);
    --db-corner: 14px;
    opacity: 0; translate: 0 12px;
    transition: opacity var(--db-andante) var(--db-exhale), translate var(--db-andante) var(--db-exhale), overlay var(--db-andante) allow-discrete, display var(--db-andante) allow-discrete;
  }
  .db-dialog[open] { opacity: 1; translate: 0 0; }
  @starting-style { .db-dialog[open] { opacity: 0; translate: 0 12px; } }
  :is(.db-dialog, .db-sheet, .db-drawer)::backdrop {
    background: color-mix(in srgb, var(--db-paper) 86%, transparent);
    -webkit-backdrop-filter: blur(6px); backdrop-filter: blur(6px);
    opacity: 0;
    transition: opacity var(--db-andante), overlay var(--db-andante) allow-discrete, display var(--db-andante) allow-discrete;
  }
  :is(.db-dialog, .db-sheet, .db-drawer)[open]::backdrop { opacity: 1; }
  @starting-style { :is(.db-dialog, .db-sheet, .db-drawer)[open]::backdrop { opacity: 0; } }
  .db-dialog-meta { margin-block-end: var(--db-space-7); }
  .db-dialog[open]::after { animation: db-frame var(--db-andante) var(--db-exhale) 80ms backwards; }
  .db-dialog[open] .db-dialog-meta > hr { transform-origin: 0 50%; animation: db-draw-x var(--db-andante) var(--db-exhale) 200ms backwards; }
  .db-dialog[open] .db-dialog-title { animation: db-breathe-out var(--db-andante) var(--db-exhale) 120ms backwards; }
  @keyframes db-frame { from { opacity: 0; scale: 0.95; } } /* opens out from inside, so the dialog never scrolls */
  @keyframes db-breathe-out { from { opacity: 0; font-weight: 500; font-stretch: 88%; } }
  .db-dialog-title .db-yours { margin-inline-start: 0.06em; } /* Bodoni's italic leans into the word before it at this size */
  .db-dialog-title { font-size: var(--db-f); line-height: var(--db-f-lh); letter-spacing: var(--db-f-tr); font-weight: 300; color: var(--db-ink); }
  .db-dialog-body { margin-block-start: var(--db-space-4); max-inline-size: 40ch; }
  .db-dialog-actions { margin: var(--db-space-7) 0 0; display: flex; flex-wrap: wrap; align-items: center; justify-content: flex-end; gap: var(--db-space-6); }
  @media (max-width: 40rem) { .db-dialog { padding: var(--db-space-7) var(--db-space-5) var(--db-space-6); } .db-dialog-meta { margin-block-end: var(--db-space-6); } .db-dialog-actions { margin-block-start: var(--db-space-6); gap: var(--db-space-5); } }
}
